IF @@TRANCOUNT<>0 OR XACT_STATE()<>0 THROW 55396,N'CSV fault preservation: Transaktionszustand weicht ab.',5;
IF (SELECT COUNT_BIG(*) FROM #CsvPositiveOutput)<>2 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveOutput WHERE DataRows=1 AND ColumnCount=4 AND DATALENGTH(CsvText)=DATALENGTH(@Text) AND CONVERT(varbinary(max),CsvText)=CONVERT(varbinary(max),@Text))<>1 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveOutput WHERE DataRows=0 AND ColumnCount=0 AND DATALENGTH(CsvText)=16777216 AND CONVERT(varbinary(max),CsvText)=CONVERT(varbinary(max),@Old))<>1 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveSource)<>4 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=1 AND [Value] IS NULL)<>1 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=2 AND [Value] IS NOT NULL AND DATALENGTH([Value])=DATALENGTH(CONVERT(nvarchar(max),N'NULL ')) AND CONVERT(varbinary(max),[Value])=CONVERT(varbinary(max),CONVERT(nvarchar(max),N'NULL ')))<>1 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=3 AND [Value] IS NOT NULL AND DATALENGTH([Value])=DATALENGTH(CONVERT(nvarchar(max),N'NULL')) AND CONVERT(varbinary(max),[Value])=CONVERT(varbinary(max),CONVERT(nvarchar(max),N'NULL')))<>1 OR (SELECT COUNT_BIG(*) FROM #CsvPositiveSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=4 AND [Value] IS NOT NULL AND DATALENGTH([Value])=DATALENGTH(@Big) AND CONVERT(varbinary(max),[Value])=CONVERT(varbinary(max),@Big))<>1 THROW 55396,N'CSV positive: voller Ergebnis-/Callerwerterhalt weicht ab.',8;
IF OBJECT_ID(N'tempdb..#CsvPositiveOutput')<>@TargetId THROW 55396,N'CSV fault preservation: Calleridentitaet weicht ab.',3;
IF EXISTS(SELECT * FROM #CsvFaultColumns EXCEPT SELECT column_id,CONVERT(varbinary(256),name) ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=@TargetId) OR EXISTS(SELECT column_id,CONVERT(varbinary(256),name) ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvFaultColumns) THROW 55396,N'CSV fault preservation: Columns-Snapshot driftet.',4;
IF EXISTS(SELECT * FROM #CsvFaultIndexes EXCEPT SELECT index_id,CONVERT(varbinary(256),name) IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=@TargetId) OR EXISTS(SELECT index_id,CONVERT(varbinary(256),name) IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvFaultIndexes) THROW 55396,N'CSV fault preservation: Indexes-Snapshot driftet.',4;
IF EXISTS(SELECT * FROM #CsvFaultKeys EXCEPT SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=@TargetId) OR EXISTS(SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvFaultKeys) THROW 55396,N'CSV fault preservation: Keys-Snapshot driftet.',4;
IF EXISTS(SELECT * FROM #CsvFaultChecks EXCEPT SELECT CONVERT(varbinary(256),name) ConstraintName,definition,is_disabled,is_not_trusted,is_not_for_replication FROM tempdb.sys.check_constraints WHERE parent_object_id=@TargetId) OR EXISTS(SELECT CONVERT(varbinary(256),name) ConstraintName,definition,is_disabled,is_not_trusted,is_not_for_replication FROM tempdb.sys.check_constraints WHERE parent_object_id=@TargetId EXCEPT SELECT * FROM #CsvFaultChecks) THROW 55396,N'CSV fault preservation: Checks-Snapshot driftet.',4;
IF OBJECT_ID(N'tempdb..#CsvPositiveSource')<>(SELECT SourceId FROM #CsvPositiveSourceIdentity) THROW 55396,N'CSV argument: Quellenidentitaet driftet.',9;
IF EXISTS(SELECT * FROM #CsvArgumentSourceColumns EXCEPT SELECT column_id,CONVERT(varbinary(256),name) ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource')) OR EXISTS(SELECT column_id,CONVERT(varbinary(256),name) ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource') EXCEPT SELECT * FROM #CsvArgumentSourceColumns) THROW 55396,N'CSV argument: Quellkatalog driftet.',4;
IF EXISTS(SELECT * FROM #CsvArgumentSourceIndexes EXCEPT SELECT index_id,CONVERT(varbinary(256),name) IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource')) OR EXISTS(SELECT index_id,CONVERT(varbinary(256),name) IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource') EXCEPT SELECT * FROM #CsvArgumentSourceIndexes) THROW 55396,N'CSV argument: Quellkatalog driftet.',4;
IF EXISTS(SELECT * FROM #CsvArgumentSourceKeys EXCEPT SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource')) OR EXISTS(SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource') EXCEPT SELECT * FROM #CsvArgumentSourceKeys) THROW 55396,N'CSV argument: Quellkatalog driftet.',4;
IF EXISTS(SELECT * FROM #CsvArgumentSourceChecks EXCEPT SELECT CONVERT(varbinary(256),name) ConstraintName,definition,is_disabled,is_not_trusted,is_not_for_replication FROM tempdb.sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource')) OR EXISTS(SELECT CONVERT(varbinary(256),name) ConstraintName,definition,is_disabled,is_not_trusted,is_not_for_replication FROM tempdb.sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'tempdb..#CsvPositiveSource') EXCEPT SELECT * FROM #CsvArgumentSourceChecks) THROW 55396,N'CSV argument: Quellkatalog driftet.',4;
DROP TABLE #CsvFaultColumns;
DROP TABLE #CsvFaultIndexes;
DROP TABLE #CsvFaultKeys;
DROP TABLE #CsvFaultChecks;
DROP TABLE #CsvArgumentSourceColumns;
DROP TABLE #CsvArgumentSourceIndexes;
DROP TABLE #CsvArgumentSourceKeys;
DROP TABLE #CsvArgumentSourceChecks;
DROP TABLE #CsvFaultIdentity;
DROP TABLE #CsvPositiveSourceIdentity;
DROP TABLE #CsvPositiveOutput;
DROP TABLE #CsvPositiveSource;
IF @@TRANCOUNT<>0 OR XACT_STATE()<>0 THROW 55396,N'CSV fault preservation: Transaktionszustand weicht ab.',5;
INSERT #CsvFaultProgress VALUES(8);
DECLARE @Cases int=(SELECT COUNT(*) FROM #CsvFaultProgress);
IF @Cases<>8 THROW 55396,N'CSV positive: Abschluss fehlt.',6;
IF @@TRANCOUNT<>0 OR XACT_STATE()<>0 THROW 55396,N'CSV fault preservation: Transaktionszustand weicht ab.',5;
DROP TABLE #CsvFaultProgress;
SELECT CONVERT(nvarchar(32),N'CSV_NULL_TOKEN_VALUE_RESULTS') Fixture,CONVERT(int,@Cases) CasesPassed;
